python3 - <<'EOF'
import pty, os, struct, fcntl, termios, subprocess, sys, time

def run(cols, rows=30):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp("fastfetch", ["fastfetch"])
    else:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        time.sleep(0.3)
        out = b""
        try:
            while True:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                out += chunk
        except OSError:
            pass
        os.waitpid(pid, 0)
        print(f"\n=== {cols} cols ===")
        sys.stdout.buffer.write(out)
        sys.stdout.flush()

for c in (30, 50, 70, 100, 160):
    run(c)
EOF

